package br.com.confirmacao.user.domain;
import br.com.confirmacao.professional.domain.Professional; import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="users",uniqueConstraints={@UniqueConstraint(name="uk_users_email",columnNames="email"),@UniqueConstraint(name="uk_users_professional",columnNames="professional_id")})
public class User{@Id private UUID id;@OneToOne(fetch=FetchType.LAZY)@JoinColumn(name="professional_id")private Professional professional;@Column(nullable=false,length=150)private String name;@Column(nullable=false,length=254)private String email;@Column(name="password_hash",nullable=false,length=255)private String passwordHash;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private UserRole role;@Column(nullable=false)private boolean active;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;protected User(){}public User(Professional p,String n,String e,String h,UserRole r){if(r==null)throw new IllegalArgumentException("O perfil do usuário é obrigatório");if(r==UserRole.ADMIN&&p!=null)throw new IllegalArgumentException("O administrador global não deve estar vinculado a um profissional");if(r==UserRole.PROFESSIONAL&&p==null)throw new IllegalArgumentException("Um usuário profissional deve estar vinculado a um profissional");id=UUID.randomUUID();professional=p;name=req(n,"O nome do usuário é obrigatório");email=req(e,"O e-mail do usuário é obrigatório").toLowerCase(Locale.ROOT);passwordHash=req(h,"A senha criptografada é obrigatória");role=r;active=true;createdAt=updatedAt=Instant.now();}public static User globalAdmin(String n,String e,String h){return new User(null,n,e,h,UserRole.ADMIN);}private String req(String v,String m){if(v==null||v.isBlank())throw new IllegalArgumentException(m);return v.trim();}public void changePasswordHash(String v){passwordHash=req(v,"A senha criptografada é obrigatória");updatedAt=Instant.now();}public void updateIdentity(String n,String e){name=req(n,"O nome do usuário é obrigatório");email=req(e,"O e-mail do usuário é obrigatório").toLowerCase(Locale.ROOT);updatedAt=Instant.now();}public void activate(){active=true;updatedAt=Instant.now();}public void deactivate(){active=false;updatedAt=Instant.now();}public UUID getId(){return id;}public Professional getProfessional(){return professional;}public String getName(){return name;}public String getEmail(){return email;}public String getPasswordHash(){return passwordHash;}public UserRole getRole(){return role;}public boolean isActive(){return active;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
